using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Store.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup()
    {
        _cart = new ShoppingCart();
    }

    // ──────────────────────────────────────────────
    // AddItem — happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotalByQuantityTimesPrice()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 3, 10.00m);

        // Assert
        Assert.AreEqual(30.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDistinctItems_TotalSumsAll()
    {
        // Arrange & Act
        _cart.AddItem("A", 1, 5.00m);
        _cart.AddItem("B", 2, 7.50m);

        // Assert
        Assert.AreEqual(20.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_QuantityIsAccumulated()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-001", 3, 10.00m);

        // Assert — 5 × 10 = 50
        Assert.AreEqual(50.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSkuDifferentPrice_UsesLatestPrice()
    {
        // Arrange & Act
        _cart.AddItem("SKU-001", 2, 10.00m);
        _cart.AddItem("SKU-001", 1, 20.00m);

        // Assert — accumulated qty 3 × latest price 20 = 60
        Assert.AreEqual(60.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_ZeroPrice_IsAllowed()
    {
        // Arrange & Act
        _cart.AddItem("FREE", 1, 0.00m);

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    // AddItem — validation errors
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void AddItem_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        var ex = Assert.ThrowsException<ArgumentException>(
            () => _cart.AddItem(sku!, 1, 5.00m));

        Assert.AreEqual("sku", ex.ParamName);
    }

    [TestMethod]
    [DataRow(0, DisplayName = "Zero quantity")]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void AddItem_InvalidQuantity_ThrowsArgumentOutOfRangeException(int quantity)
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", quantity, 5.00m));

        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        var ex = Assert.ThrowsException<ArgumentOutOfRangeException>(
            () => _cart.AddItem("SKU-001", 1, -1.00m));

        Assert.AreEqual("price", ex.ParamName);
    }

    // ──────────────────────────────────────────────
    // RemoveItem — happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromTotal()
    {
        // Arrange
        _cart.AddItem("A", 2, 5.00m);
        _cart.AddItem("B", 1, 10.00m);

        // Act
        _cart.RemoveItem("A");

        // Assert — only B remains: 1 × 10 = 10
        Assert.AreEqual(10.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_OnlyItem_CartBecomesEmpty()
    {
        // Arrange
        _cart.AddItem("A", 1, 25.00m);

        // Act
        _cart.RemoveItem("A");

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    // RemoveItem — validation errors
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "Null SKU")]
    [DataRow("", DisplayName = "Empty SKU")]
    public void RemoveItem_NullOrEmptySku_ThrowsArgumentException(string? sku)
    {
        var ex = Assert.ThrowsException<ArgumentException>(
            () => _cart.RemoveItem(sku!));

        Assert.AreEqual("sku", ex.ParamName);
    }

    [TestMethod]
    public void RemoveItem_NonexistentSku_ThrowsKeyNotFoundException()
    {
        Assert.ThrowsException<KeyNotFoundException>(
            () => _cart.RemoveItem("DOES-NOT-EXIST"));
    }

    // ──────────────────────────────────────────────
    // CalculateTotal
    // ──────────────────────────────────────────────

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_AfterAddAndRemove_ReflectsRemainingItems()
    {
        // Arrange
        _cart.AddItem("A", 3, 10.00m);
        _cart.AddItem("B", 2, 5.00m);
        _cart.RemoveItem("A");

        // Assert — only B: 2 × 5 = 10
        Assert.AreEqual(10.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    // ApplyCoupon — happy path
    // ──────────────────────────────────────────────

    [TestMethod]
    public void ApplyCoupon_Save10_ReducesTotalBy10Percent()
    {
        // Arrange
        _cart.AddItem("A", 1, 100.00m);

        // Act
        _cart.ApplyCoupon("SAVE10");

        // Assert
        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_Save20_ReducesTotalBy20Percent()
    {
        // Arrange
        _cart.AddItem("A", 1, 100.00m);

        // Act
        _cart.ApplyCoupon("SAVE20");

        // Assert
        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_LastCouponWins_OverridesPrevious()
    {
        // Arrange
        _cart.AddItem("A", 2, 50.00m);
        _cart.ApplyCoupon("SAVE10");

        // Act — override with SAVE20
        _cart.ApplyCoupon("SAVE20");

        // Assert — 100 × 0.8 = 80
        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_OnEmptyCart_TotalRemainsZero()
    {
        // Act
        _cart.ApplyCoupon("SAVE10");

        // Assert
        Assert.AreEqual(0.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_ThenAddItems_DiscountStillApplies()
    {
        // Arrange — coupon first, items second
        _cart.ApplyCoupon("SAVE20");
        _cart.AddItem("A", 5, 20.00m);

        // Assert — 100 × 0.8 = 80
        Assert.AreEqual(80.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    // ApplyCoupon — validation errors
    // ──────────────────────────────────────────────

    [TestMethod]
    [DataRow(null, DisplayName = "Null code")]
    [DataRow("", DisplayName = "Empty code")]
    public void ApplyCoupon_NullOrEmptyCode_ThrowsArgumentException(string? code)
    {
        var ex = Assert.ThrowsException<ArgumentException>(
            () => _cart.ApplyCoupon(code!));

        Assert.AreEqual("code", ex.ParamName);
    }

    [TestMethod]
    [DataRow("INVALID", DisplayName = "Unknown code")]
    [DataRow("save10", DisplayName = "Wrong case")]
    public void ApplyCoupon_UnrecognizedCode_ThrowsArgumentException(string code)
    {
        var ex = Assert.ThrowsException<ArgumentException>(
            () => _cart.ApplyCoupon(code));

        Assert.AreEqual("code", ex.ParamName);
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_DoesNotAlterPreviousDiscount()
    {
        // Arrange
        _cart.AddItem("A", 1, 100.00m);
        _cart.ApplyCoupon("SAVE10");

        // Act — invalid coupon should throw but not change discount
        Assert.ThrowsException<ArgumentException>(
            () => _cart.ApplyCoupon("BOGUS"));

        // Assert — SAVE10 still in effect
        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    // ──────────────────────────────────────────────
    // Integration / multi-operation scenarios
    // ──────────────────────────────────────────────

    [TestMethod]
    public void FullWorkflow_AddRemoveCoupon_ProducesCorrectTotal()
    {
        // Arrange
        _cart.AddItem("WIDGET", 4, 25.00m);  // 100
        _cart.AddItem("GADGET", 1, 50.00m);  // 50
        _cart.RemoveItem("GADGET");
        _cart.ApplyCoupon("SAVE10");

        // Assert — 100 × 0.9 = 90
        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_LargeQuantityAndDecimalPrice_ComputesAccurately()
    {
        // Arrange & Act
        _cart.AddItem("PRECISE", 1000, 0.01m);

        // Assert — 1000 × 0.01 = 10.00
        Assert.AreEqual(10.00m, _cart.CalculateTotal());
    }
}

