    }

    [TestMethod]
    public void RemoveItem_ThenReAddSameSku_TreatedAsFreshItem()
    {
        // Arrange
        _cart.AddItem("A", 5, 10.00m);
        _cart.RemoveItem("A");

        // Act — re-add with different quantity/price
        _cart.AddItem("A", 2, 20.00m);

        // Assert — 2 × 20 = 40, not accumulated with old quantity
        Assert.AreEqual(40.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItemsWithCoupon_AppliesDiscountToEntireSum()
    {
        // Arrange
        _cart.AddItem("X", 3, 10.00m); // 30
        _cart.AddItem("Y", 2, 20.00m); // 40
        _cart.ApplyCoupon("SAVE10");

        // Assert — (30 + 40) × 0.9 = 63
        Assert.AreEqual(63.00m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_QuantityExactlyOne_DoesNotThrow()
    {
        // Boundary: quantity = 1 (minimum valid)
        _cart.AddItem("SINGLE", 1, 9.99m);

        Assert.AreEqual(9.99m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_CalledMultipleTimes_ReturnsSameValue()
    {
        // Verify CalculateTotal is idempotent (doesn't mutate state)
        _cart.AddItem("A", 2, 15.00m);

        var first = _cart.CalculateTotal();
        var second = _cart.CalculateTotal();

        Assert.AreEqual(30.00m, first);
        Assert.AreEqual(first, second);
    }

    [TestMethod]
    public void ApplyCoupon_Save10ThenSave20ThenSave10Again_LastOneWins()
    {
        // Arrange
        _cart.AddItem("A", 1, 100.00m);

        // Act — cycle through coupons
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("SAVE20");
        _cart.ApplyCoupon("SAVE10");

        // Assert — final coupon is SAVE10 → 90
        Assert.AreEqual(90.00m, _cart.CalculateTotal());
    }
}

